<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {getPreferences,addPreference,editPreference,deletePreference,acceptPreference,type Preferences,type Preference} from '../../api/preferences'
import {errorText} from '../../api/http'
const data=ref<Preferences>(),error=ref(''),busy=ref(false),category=ref('teaching'),value=ref(''),editing=ref<string|null>(null)
const names:Record<string,string>={teaching:'教学方式',expression:'表达偏好',visual:'画风偏好',settings:'常用设置'}
async function load(){try{data.value=await getPreferences();value.value=data.value.options[category.value]?.[0]??''}catch(e){error.value=errorText(e)}}
watch(category,()=>{value.value=data.value?.options[category.value]?.[0]??''})
async function save(){if(!value.value)return;busy.value=true;error.value='';try{if(editing.value)await editPreference(editing.value,category.value,value.value);else await addPreference(category.value,value.value);editing.value=null;await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function remove(p:Preference){try{await ElMessageBox.confirm('删除此偏好后，后续大纲不再使用它。','删除偏好',{type:'warning'});await deletePreference(p.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}}
async function accept(p:Preference){busy.value=true;try{await acceptPreference(p.id);await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function edit(p:Preference){editing.value=p.id;category.value=p.category;void Promise.resolve().then(()=>{value.value=p.value})}
onMounted(load)
</script>
<template><section class="preferences"><h1>我的偏好</h1><p class="ev-muted">只保存你明确选择的教学方式与表达偏好。本次具体要求优先于长期偏好，讲稿和事实不进入记忆。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="data&&!data.enabled" title="管理员已关闭长期偏好；已有数据保留，当前不会读取或用于生成。" type="warning" :closable="false"/><template v-if="data?.enabled"><div class="card-grid" data-testid="preferences-card-grid"><div class="card"><h2>{{editing?'修改偏好':'添加偏好'}}</h2><el-form label-position="top" @submit.prevent="save"><div class="fields"><el-form-item label="类型"><el-select v-model="category" aria-label="偏好类型" popper-class="preferences-select-popper"><el-option v-for="(label,key) in names" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="偏好内容"><el-select v-model="value" aria-label="偏好内容" popper-class="preferences-select-popper"><el-option v-for="item in data.options[category]" :key="item" :label="item" :value="item"/></el-select></el-form-item></div><el-button type="primary" native-type="submit" :loading="busy">{{editing?'保存修改':'确认保存偏好'}}</el-button><el-button v-if="editing" @click="editing=null">取消修改</el-button></el-form></div><div class="card"><h2>已保存偏好</h2><el-empty v-if="!data.items.length" description="还没有保存偏好，你可以自行添加"/><ul><li v-for="p in data.items" :key="p.id"><div><small>{{names[p.category]}}</small><strong>{{p.value}}</strong></div><div><el-button text @click="edit(p)">编辑</el-button><el-button text type="danger" @click="remove(p)">删除</el-button></div></li></ul></div></div><div v-if="data.suggestions.length" class="card"><h2>待你确认的建议</h2><p class="ev-muted">根据你重复提交的明确改写要求整理，接受前不会用于后续生成。</p><ul><li v-for="p in data.suggestions" :key="p.id"><div><strong>{{p.value}}</strong><p>{{p.reason}}</p></div><el-button :loading="busy" @click="accept(p)">接受并保存</el-button></li></ul></div></template></section></template>
<style scoped>.preferences{width:100%;max-width:none}h1{font:600 28px/1.4 var(--ev-font-display);margin:0}h2{font-size:16px;margin:0 0 20px}.card-grid{display:grid;grid-template-columns:1fr;gap:22px;align-items:stretch;margin-top:22px}.card{border:1px solid var(--ev-color-border);border-radius:var(--ev-radius);background:var(--ev-color-surface);padding:26px;margin:0;box-shadow:none}.fields{display:grid;grid-template-columns:1fr 2fr;gap:20px}.fields .el-form-item{margin-bottom:24px}.fields :deep(.el-select){width:100%}.fields :deep(.el-select__wrapper){min-height:44px;padding:0 13px;border:1px solid var(--ev-color-border-strong);border-radius:8px;background:var(--ev-color-surface);box-shadow:none;font-size:14px}.fields :deep(.el-select__wrapper:hover){border-color:var(--ev-color-primary)}.fields :deep(.el-select__wrapper.is-focused){border-color:var(--ev-color-primary);box-shadow:0 0 0 2px var(--el-color-primary-light-9);background:var(--ev-color-surface)}.fields :deep(.el-select__selected-item){color:var(--ev-color-text);font-weight:400}.fields :deep(.el-select__placeholder){color:var(--ev-color-muted)}ul{padding:0;list-style:none}li{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--ev-color-border)}small,strong{display:block}small{color:var(--ev-color-muted);margin-bottom:6px}p{line-height:1.7}.card-grid+.card{margin-top:22px}:global(.preferences-select-popper){border:1px solid var(--ev-color-border-strong)!important;border-radius:6px!important;background:var(--ev-color-surface)!important;box-shadow:0 8px 20px rgba(24,58,107,.10)!important;padding:0!important}:global(.preferences-select-popper .el-select-dropdown__list){padding:4px 0!important}:global(.preferences-select-popper .el-select-dropdown__item){height:40px;padding:0 16px;border-radius:0;border-bottom:0!important;color:var(--ev-color-text);font-size:14px;line-height:40px;margin:0}:global(.preferences-select-popper .el-select-dropdown__item.hover),:global(.preferences-select-popper .el-select-dropdown__item:hover){background:#f5f6f8;color:var(--ev-color-text)}:global(.preferences-select-popper .el-select-dropdown__item.is-selected){background:#f1f3f6;color:var(--ev-color-primary);font-weight:700}:global(.preferences-select-popper .el-select-dropdown__empty){padding:14px;color:var(--ev-color-muted)}@media(max-width:600px){.fields{grid-template-columns:1fr;gap:0}.card{padding:16px}li{flex-wrap:wrap}}</style>
